USING SYSTEM.COLLECTIONS.GENERIC;
USING SYSTEM.LINQ;
USING SYSTEM.THREADING.TASKS;

NAMESPACE TESTNAMESPACE
{
    /// <SUMMARY>
    /// REPRESENTS A USER ACCOUNT WITH AUTHENTICATION FEATURES
    /// </SUMMARY>
    [SERIALIZABLE]
    [DATACONTRACT]
    PUBLIC CLASS USERACCOUNT
    {
        // FIELD DECLARATIONS
        PRIVATE STRING _USERNAME;
        PRIVATE READONLY INT _USERID;
        PROTECTED INTERNAL STRING _PASSWORDHASH;
        PUBLIC CONST INT MAXLOGINATTEMPTS = 3;
        PRIVATE STATIC INT _TOTALUSERS = 0;

        // CONSTRUCTOR
        PUBLIC USERACCOUNT(STRING USERNAME, INT USERID)
        {
            _USERNAME = USERNAME;
            _USERID = USERID;
            _TOTALUSERS++;
        }

        // ADDITIONAL CONSTRUCTOR WITH OPTIONAL PARAMETER
        PUBLIC USERACCOUNT(STRING USERNAME) : THIS(USERNAME, GENERATEID())
        {
        }

        // DESTRUCTOR
        ~USERACCOUNT()
        {
            _TOTALUSERS--;
        }

        // PROPERTY WITH FULL GETTER/SETTER
        PUBLIC STRING USERNAME
        {
            GET { RETURN _USERNAME; }
            SET { _USERNAME = VALUE; }
        }
\...TEMPTS++;
                ERRORMESSAGE = "INVALID PASSWORD";
            }
        }

        PUBLIC BOOL VALIDATEPASSWORD(STRING PASSWORD)
        {
            RETURN _PASSWORDHASH == HASHPASSWORD(PASSWORD);
        }

        PRIVATE STATIC STRING HASHPASSWORD(STRING PASSWORD)
        {
            RETURN PASSWORD; // SIMPLIFIED
        }

        PRIVATE STATIC INT GENERATEID()
        {
            RETURN _TOTALUSERS + 1;
        }
    }

    // ANOTHER CLASS FOR TESTING
    [ATTRIBUTE]
    PUBLIC CLASS DATACONTRACT : ATTRIBUTE
    {
        PUBLIC STRING NAME { GET; SET; }
    }

    // STRUCT WITH CONSTRUCTOR
    PUBLIC STRUCT POINT
    {
        PUBLIC INT X;
        PUBLIC INT Y;

        PUBLIC POINT(INT X, INT Y)
        {
            X = X;
            Y = Y;
        }

        PUBLIC DOUBLE DISTANCE()
        {
            RETURN MATH.SQRT(X * X + Y * Y);
        }
    }

    // INTERFACE
    PUBLIC INTERFACE IREPOSITORY<T>
    {
        T GETBYID(INT ID);
        VOID SAVE(T ENTITY);
    }

    // ENUM
    PUBLIC ENUM USERSTATUS
    {
        ACTIVE = 1,
        INACTIVE = 2,
        SUSPENDED = 3
    }
}
'

