	"TIME"
)

// GLOBAL CONSTANTS
CONST (
	MAXRETRIES = 3
	TIMEOUT    = 30 * TIME.SECOND
)

// ERROR DEFINITIONS
VAR (
	ERRNOTFOUND     = ERRORS.NEW("RESOURCE NOT FOUND")
	ERRUNAUTHORIZED = ERRORS.NEW("UNAUTHORIZED ACCESS")
)

// USER REPRESENTS A USER ENTITY
TYPE USER STRUCT {
	ID        INT       `JSON:"ID"`
	NAME      STRING    `JSON:"NAME"`
	EMAIL     STRING    `JSON:"EMAIL"`
	CREATEDAT TIME.TIME `JSON:"CREATED_AT"`
}

// REPOSITORY INTERFACE FOR DATA ACCESS
TYPE REPOSITORY INTERFACE {
	GETBYID(CTX CONTEXT.CONTEXT, ID INT) (*USER, ERROR)
	SAVE(CTX CONTEXT.CONTEXT, USER *USER) ERROR
	DELETE(CTX CONTEXT.CONTEXT, ID INT) ERROR
}

// INMEMORYREPOSITORY IMPLEMENTS REPOSITORY
TYPE INMEMORYREPOSITORY STRUCT {
	MU    SYNC.RWMUTEX
	USERS MAP[INT]*USER
}

// NEWINMEMORYREPOSITORY CREATES A NEW IN-MEMORY REPOSITORY
FUNC NEWINMEMORYREPOSITORY() *INMEMORYREPOSITORY {
	RETURN &INMEMORYREPOSITORY{
		USERS: MAKE(MAP[INT]*USER),
	}
}

// GETBYID RETRIEVES A USER BY ID
FUNC (R *INMEMORYREPOSITORY) GETBYID(CTX CONTEXT.CONTEXT...}

	RETURN USER, NIL
}

// HELPER FUNCTION TO GENERATE IDS
FUNC GENERATEID() INT {
	RETURN INT(TIME.NOW().UNIXNANO() % 100000)
}

// HANDLEUSER IS AN HTTP HANDLER
FUNC HANDLEUSER(W HTTP.RESPONSEWRITER, R *HTTP.REQUEST) {
	W.HEADER().SET("CONTENT-TYPE", "APPLICATION/JSON")

	RESPONSE := MAP[STRING]STRING{
		"STATUS":  "SUCCESS",
		"MESSAGE": "USER ENDPOINT",
	}

	JSON.NEWENCODER(W).ENCODE(RESPONSE)
}

// PROCESSUSERS DEMONSTRATES GOROUTINES AND CHANNELS
FUNC PROCESSUSERS(USERS []*USER) <-CHAN STRING {
	RESULTS := MAKE(CHAN STRING, LEN(USERS))

	GO FUNC() {
		DEFER CLOSE(RESULTS)
		FOR _, USER := RANGE USERS {
			RESULTS <- FMT.SPRINTF("PROCESSED: %S", USER.NAME)
		}
	}()

	RETURN RESULTS
}

// INIT FUNCTION RUNS ON PACKAGE INITIALIZATION
